"use client"

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * La búsqueda reutiliza foldInboxText. El filtro reutiliza segmented-filter.
 */

import { useId, useState, type KeyboardEvent } from "react"

import { cn } from "@/lib/utils"
import type { ConversationItemData, ConversationSection, ThreadFilter, ThreadStatus } from "@/lib/thread-desk"
import { matchesConversation } from "@/lib/thread-desk"
import { ConversationItem } from "@/components/ui/conversation-item"
import { SegmentedFilter } from "@/components/ui/segmented-filter"

export type ConversationListProps = {
  label: string
  title?: string
  countLabel?: string
  searchLabel?: string
  shortcut?: string
  query?: string
  onQueryChange?: (query: string) => void
  filters?: readonly ThreadFilter[]
  filter?: string
  onFilterChange?: (value: string) => void
  sections?: readonly ConversationSection[]
  items?: readonly ConversationItemData[]
  selectedId?: string | null
  onSelect?: (id: string) => void
  status?: ThreadStatus
  emptyTitle?: string
  loadingLabel?: string
  error?: string
  onRetry?: () => void
  retryLabel?: string
  className?: string
}

export function ConversationList({
  label,
  title,
  countLabel,
  searchLabel = "Buscar",
  shortcut,
  query: queryProp,
  onQueryChange,
  filters,
  filter,
  onFilterChange,
  sections,
  items = [],
  selectedId,
  onSelect,
  status = "ready",
  emptyTitle = "Sin conversaciones",
  loadingLabel = "Cargando conversaciones",
  error,
  onRetry,
  retryLabel = "Reintentar",
  className,
}: ConversationListProps) {
  const listId = useId()
  const [queryState, setQueryState] = useState("")
  const query = queryProp ?? queryState
  const visible = items.filter((item) => matchesConversation(item, filter, query))

  function setQuery(next: string) {
    if (queryProp === undefined) setQueryState(next)
    onQueryChange?.(next)
  }

  function onListKey(event: KeyboardEvent<HTMLDivElement>) {
    if (!visible.length) return
    const index = Math.max(0, visible.findIndex((item) => item.id === selectedId))
    const nextIndex = event.key === "ArrowDown" ? Math.min(visible.length - 1, index + 1) : event.key === "ArrowUp" ? Math.max(0, index - 1) : -1
    if (nextIndex < 0) {
      if (event.key === "Enter" && visible[index]) onSelect?.(visible[index].id)
      return
    }
    event.preventDefault()
    const next = visible[nextIndex]
    if (next) onSelect?.(next.id)
  }

  const known = new Set((sections ?? []).map((section) => section.id))
  const groups = sections?.length
    ? [
        ...sections.map((section) => ({ ...section, rows: visible.filter((item) => item.section === section.id) })),
        ...[...new Set(visible.map((item) => item.section).filter((id): id is string => typeof id === "string" && !known.has(id)))].map((id) => ({
          id,
          label: id,
          hint: undefined,
          rows: visible.filter((item) => item.section === id),
        })),
      ]
    : [{ id: "all", label: "", hint: undefined, rows: visible }]

  return (
    <section data-slot="conversation-list" className={cn("flex min-h-0 min-w-0 flex-col gap-3", className)}>
      {title || countLabel ? (
        <div className="flex items-center justify-between gap-2 px-1">
          {title ? <h2 className="truncate text-sm font-semibold">{title}</h2> : <span />}
          {countLabel ? (
            <p className="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground tabular-nums">
              <span className="sr-only">{`Total ${countLabel}`}</span>
              <span aria-hidden>{countLabel}</span>
            </p>
          ) : null}
        </div>
      ) : null}
      <div className="relative">
        <input
          type="search"
          data-slot="conversation-search"
          value={query}
          aria-label={searchLabel}
          placeholder={searchLabel}
          onChange={(event) => setQuery(event.target.value)}
          className="h-11 w-full rounded-xl border border-input bg-background ps-3 pe-14 text-sm focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
        />
        {shortcut ? (
          <kbd className="pointer-events-none absolute end-2 top-1/2 -translate-y-1/2 rounded-md bg-muted px-1.5 py-0.5 text-[11px] text-muted-foreground">
            {shortcut}
          </kbd>
        ) : null}
      </div>
      {filters?.length ? (
        <SegmentedFilter label={label} options={[...filters]} value={filter} onValueChange={onFilterChange} />
      ) : null}
      {status === "loading" ? (
        <div role="status" aria-label={loadingLabel} className="grid gap-2">
          <span className="sr-only">{loadingLabel}</span>
          <span className="h-14 animate-pulse rounded-xl bg-muted" />
          <span className="h-14 animate-pulse rounded-xl bg-muted" />
        </div>
      ) : null}
      {status === "error" ? (
        <div role="alert" className="grid gap-2 rounded-xl border border-border p-3">
          <p className="text-sm text-destructive">{error}</p>
          {onRetry ? (
            <button type="button" className="h-11 rounded-full bg-foreground px-4 text-sm text-background" onClick={onRetry}>
              {retryLabel}
            </button>
          ) : null}
        </div>
      ) : null}
      {status === "empty" || (status === "ready" && visible.length === 0) ? (
        <div role="status" className="px-2 py-8 text-center text-sm text-muted-foreground">
          {emptyTitle}
        </div>
      ) : null}
      {status === "ready" && visible.length > 0 ? (
        <div
          role="listbox"
          aria-label={label}
          tabIndex={0}
          className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto outline-none focus-visible:ring-2 focus-visible:ring-ring"
          onKeyDown={onListKey}
        >
          {groups.map((group) =>
            group.rows.length ? (
              <div key={group.id} className="grid gap-1">
                {group.label ? (
                  <p className="px-2 text-[11px] font-medium tracking-wide text-muted-foreground uppercase">
                    {group.label}
                    {group.hint ? <span className="ms-2 normal-case tracking-normal">{group.hint}</span> : null}
                  </p>
                ) : null}
                {group.rows.map((item) => (
                  <ConversationItem key={item.id} id={`${listId}-${item.id}`} item={item} selected={item.id === selectedId} onSelect={onSelect} />
                ))}
              </div>
            ) : null,
          )}
        </div>
      ) : null}
    </section>
  )
}

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Tipos y puertos. Sin red, sin Supabase y sin dominio de un canal.
 */

import type { CSSProperties, ReactNode } from "react"

import { foldInboxText, type DeskPresence } from "@/lib/inbox"

/** Online uses the host success token, then chart-2. It is not the accent. */
export function presenceDotStyle(presence: DeskPresence): CSSProperties {
  if (presence === "online") return { backgroundColor: "var(--success, var(--chart-2))" }
  if (presence === "offline") return { backgroundColor: "var(--muted-foreground)" }
  return { backgroundColor: "var(--accent-foreground)" }
}

export type ThreadStatus = "ready" | "loading" | "empty" | "error" | "offline"

export type ThreadFilter = {
  value: string
  label: string
}

export type ConversationSection = {
  id: string
  label: string
  hint?: string
}

export type ConversationItemData = {
  id: string
  title: string
  preview?: string
  time?: string
  unread?: number
  section?: string
  tags?: readonly string[]
  presence?: DeskPresence
  role?: string
  kind?: "thread" | "contact"
  stage?: string
  windowLabel?: string
  channel?: ReactNode
}

export type DeliveryState = "sending" | "sent" | "delivered" | "read" | "failed"

export type ThreadNote = {
  title: string
  detail: string
  body?: string
}

export type ThreadFile = {
  name: string
  detail: string
  status?: string
}

export type ThreadInvoice = {
  title: string
  amount: string
  due: string
}

export type ThreadMetric = {
  title: string
  chip?: string
  value: string
  caption?: string
  filled: number
  total: number
  start: string
  end: string
}

export type ThreadMessageData = {
  id: string
  side: "incoming" | "outgoing"
  author: string
  time?: string
  body?: string
  delivery?: DeliveryState
  deliveryLabel?: string
  grouped?: "single" | "start" | "middle" | "end"
  enter?: boolean
  note?: ThreadNote
  file?: ThreadFile
  invoice?: ThreadInvoice
  metric?: ThreadMetric
}

export type SuggestionItem = {
  id: string
  label: string
}

export type SecretField = {
  id: string
  label: string
  masked: string
  revealed: string
}

export type PartyFact = {
  id: string
  label: string
  value: string
}

export type PartyMember = {
  id: string
  name: string
  role: string
}

export type PartyFile = {
  id: string
  name: string
  detail: string
}

export type PartyDeal = {
  title: string
  status: string
  amount: string
  value: number
  label: string
}

export type PartyPanelData = {
  name: string
  meta?: string
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
}

export function matchesConversation(item: ConversationItemData, filter: string | undefined, query: string) {
  if (filter && filter !== "all") {
    const tagged = item.tags?.includes(filter) || (filter === "unread" && (item.unread ?? 0) > 0)
    if (!tagged) return false
  }
  const needle = query.trim()
  if (!needle) return true
  const hay = [item.title, item.preview, item.role, item.stage, item.windowLabel].filter(Boolean).join(" ")
  return foldInboxText(hay).includes(foldInboxText(needle))
}

export function groupMessages(messages: readonly ThreadMessageData[]): ThreadMessageData[] {
  return messages.map((message, index) => {
    if (message.grouped) return message
    const prev = messages[index - 1]
    const next = messages[index + 1]
    const same = (other?: ThreadMessageData) =>
      Boolean(other && other.side === message.side && other.author === message.author && !other.file && !other.invoice && !other.metric && !message.file && !message.invoice && !message.metric)
    const before = same(prev)
    const after = same(next)
    const grouped = before && after ? "middle" : before ? "end" : after ? "start" : "single"
    return { ...message, grouped }
  })
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}
